-- Monarch Codex published investment package catalogue.
-- Back up production before applying. Existing member investments and ledger records are untouched.
-- Monthly profit terms are displayed as the stated 10% rate; earnings must still be
-- recorded through the existing approved financial workflow, never fabricated by this migration.

INSERT INTO investment_packages (name,description,currency,price,duration_days,terms,status,created_by)
SELECT v.name,v.description,'USD',v.price,NULL,v.terms,'active',NULL
FROM (
  SELECT 'Monarch Starter' AS name,
    'A starting package for members beginning their Monarch Codex investment journey. Review the monthly profit terms, purchase fee and account requirements before committing funds.' AS description,
    50.00 AS price,
    'Stated monthly profit rate: 10% of the invested principal per month. Example: $50 principal corresponds to $5 for a full month at the stated rate. Profit must be calculated for the actual eligible period and recorded through the authorised earnings ledger. Purchase fee: 1% in addition to package price. Investment capital and profits are not credited to a wallet by this catalogue migration.' AS terms
  UNION ALL SELECT 'Monarch Growth', 'A growth-tier package for members seeking a larger allocation within the Monarch Codex investment catalogue.',100.00,'Stated monthly profit rate: 10% of the invested principal per month. Example: $100 principal corresponds to $10 for a full month at the stated rate. Profit must be calculated for the actual eligible period and recorded through the authorised earnings ledger. Purchase fee: 1% in addition to package price. Investment capital and profits are not credited to a wallet by this catalogue migration.'
  UNION ALL SELECT 'Monarch Advance', 'An advanced allocation tier for members choosing a higher investment amount.',200.00,'Stated monthly profit rate: 10% of the invested principal per month. Example: $200 principal corresponds to $20 for a full month at the stated rate. Profit must be calculated for the actual eligible period and recorded through the authorised earnings ledger. Purchase fee: 1% in addition to package price. Investment capital and profits are not credited to a wallet by this catalogue migration.'
  UNION ALL SELECT 'Monarch Elite', 'A higher-tier package for members selecting a substantial investment allocation.',500.00,'Stated monthly profit rate: 10% of the invested principal per month. Example: $500 principal corresponds to $50 for a full month at the stated rate. Profit must be calculated for the actual eligible period and recorded through the authorised earnings ledger. Purchase fee: 1% in addition to package price. Investment capital and profits are not credited to a wallet by this catalogue migration.'
  UNION ALL SELECT 'Monarch Premium', 'A premium package tier for members selecting a larger capital allocation.',1000.00,'Stated monthly profit rate: 10% of the invested principal per month. Example: $1,000 principal corresponds to $100 for a full month at the stated rate. Profit must be calculated for the actual eligible period and recorded through the authorised earnings ledger. Purchase fee: 1% in addition to package price. Investment capital and profits are not credited to a wallet by this catalogue migration.'
  UNION ALL SELECT 'Sovereign', 'The highest-tier package in the Monarch Codex catalogue, intended for members selecting the Sovereign allocation.',2000.00,'Stated monthly profit rate: 10% of the invested principal per month. Example: $2,000 principal corresponds to $200 for a full month at the stated rate. Profit must be calculated for the actual eligible period and recorded through the authorised earnings ledger. Purchase fee: 1% in addition to package price. Investment capital and profits are not credited to a wallet by this catalogue migration.'
) AS v
WHERE NOT EXISTS (SELECT 1 FROM investment_packages p WHERE p.name=v.name AND p.currency='USD');

-- Refresh the catalogue descriptions, prices and stated terms for these named plans.
-- Preserve each package's active/draft/inactive decision made by the administrator.
UPDATE investment_packages SET description='A starting package for members beginning their Monarch Codex investment journey. Review the monthly profit terms, purchase fee and account requirements before committing funds.', price=50.00, terms='Stated monthly profit rate: 10% of the invested principal per month. Example: $50 principal corresponds to $5 for a full month at the stated rate. Profit must be calculated for the actual eligible period and recorded through the authorised earnings ledger. Purchase fee: 1% in addition to package price. Investment capital and profits are not credited to a wallet by this catalogue migration.' WHERE name='Monarch Starter' AND currency='USD';
